<?php
declare(strict_types=1);
error_reporting(E_ALL);ini_set('display_errors','1');
require_once __DIR__.'/database/schema.php';
require_once __DIR__.'/database/schema_v5.php';

$messages=[];$done=false;
function ih($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if($_SERVER['REQUEST_METHOD']==='POST'){
    $host=trim($_POST['db_host']??'localhost');$port=trim($_POST['db_port']??'3306');$name=trim($_POST['db_name']??'');$user=trim($_POST['db_user']??'');$pass=(string)($_POST['db_pass']??'');$url=rtrim(trim($_POST['site_url']??''),'/');$fresh=!empty($_POST['fresh']);$confirm=trim($_POST['confirm']??'');
    try{
        if($name===''||$user===''||$url==='')throw new RuntimeException('Veritabanı adı, kullanıcı adı ve site adresi zorunludur.');
        if(!filter_var($url,FILTER_VALIDATE_URL))throw new RuntimeException('Site adresini https://alanadi.com/klasor biçiminde girin.');
        if($fresh&&$confirm!=='TOPLUCA SIFIRLA')throw new RuntimeException('Sıfır kurulum için onay alanına TOPLUCA SIFIRLA yazın.');
        $pdo=new PDO('mysql:host='.$host.';port='.$port.';dbname='.$name.';charset=utf8mb4',$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
        if($fresh){
            $pdo->exec('SET FOREIGN_KEY_CHECKS=0');
            foreach(['content_pages','homepage_feature_boxes','admin_roles','theme_schedules'] as $t)$pdo->exec('DROP TABLE IF EXISTS `'.$t.'`');
            drop_topluca_tables($pdo);
        }
        foreach(schema_sql() as $sql)$pdo->exec($sql);
        seed_v4($pdo);
        apply_v5_schema($pdo);
        $pdo->prepare("INSERT INTO settings(setting_key,setting_value) VALUES('site_url',?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)")->execute([$url]);
        $cfg="<?php\nreturn ".var_export(['db'=>['host'=>$host,'port'=>$port,'name'=>$name,'user'=>$user,'pass'=>$pass],'app'=>['name'=>'TOPLUCA','url'=>$url,'timezone'=>'Europe/Istanbul','version'=>'5.1.0']],true).";\n";
        if(file_put_contents(__DIR__.'/config.php',$cfg)===false)throw new RuntimeException('config.php yazılamadı. Klasör yazma iznini kontrol edin.');
        foreach(['products','banners','brands','categories','site','themes'] as $folder){$dir=__DIR__.'/uploads/'.$folder;if(!is_dir($dir)&&!@mkdir($dir,0755,true))throw new RuntimeException('uploads/'.$folder.' klasörü oluşturulamadı.');}
        file_put_contents(__DIR__.'/.installed','TOPLUCA V5.1 '.date('c'));
        $done=true;
    }catch(Throwable $e){$messages[]=$e->getMessage();}
}
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TOPLUCA V5.1 Kurulum</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f6f8;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;color:#171717}.wrap{max-width:880px;margin:48px auto;padding:0 18px}.card{background:#fff;border:1px solid #e4e7eb;border-radius:20px;padding:34px;box-shadow:0 18px 60px rgba(24,29,35,.07)}h1{font-size:28px;margin:0 0 8px;letter-spacing:-.6px}.orange{color:#ff6000}.muted{color:#6f7780;font-size:13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:24px}label{font-size:12px;font-weight:750;color:#353b42}input{display:block;width:100%;margin-top:6px;padding:12px 13px;border:1px solid #d9dee4;border-radius:9px;outline:none}input:focus{border-color:#ff6000;box-shadow:0 0 0 3px rgba(255,96,0,.08)}.full{grid-column:1/-1}.danger{padding:16px;background:#fff7f2;border:1px solid #ffd7c0;border-radius:11px;margin:20px 0}.error{background:#fff0f0;color:#a62d2d;padding:12px;border-radius:9px;margin:8px 0}.success{background:#ecf8f0;color:#176b38;padding:22px;border-radius:12px}button,.btn{display:inline-flex;align-items:center;justify-content:center;border:0;background:#ff6000;color:#fff;padding:13px 18px;border-radius:9px;font-weight:800;text-decoration:none;cursor:pointer}.btn.dark{background:#17191c}.note{padding:13px 15px;border-radius:10px;background:#f7f8fa;border:1px solid #e5e8eb;font-size:12px;color:#5e6670;margin-top:18px}@media(max-width:650px){.grid{grid-template-columns:1fr}.full{grid-column:auto}.wrap{margin:18px auto}.card{padding:22px}}</style></head><body><div class="wrap"><div class="card"><h1>TOPLU<span class="orange">CA</span> V5.1 Professional</h1><p class="muted">PHP 8.0+ • MySQL • Profesyonel vitrin, checkout ve WebYönet</p><?php foreach($messages as $m):?><div class="error"><?=ih($m)?></div><?php endforeach;?><?php if($done):?><div class="success"><h2>Kurulum tamamlandı 🎉</h2><p>V5.1 veritabanı, SEO, banner, tema, üyelik, sipariş, stok, kargo ve WebYönet altyapısı hazır.</p><p><b>WebYönet:</b> emrah / emr321456</p><p>İlk girişte yönetici şifresini değiştirin. Ardından WebYönet → Site & SEO Ayarları bölümünden özgün TOPLUCA logonuzu yükleyebilirsiniz.</p><p><a class="btn dark" href="index.php">Siteyi Aç</a> <a class="btn" href="webyonet/">WebYönet</a></p><p><b>Güvenlik:</b> Kurulumdan sonra install.php dosyasını sunucudan kaldırın.</p></div><?php else:?><div class="note">MySQL kullanıcı adı, Plesk giriş kullanıcısı değildir. Plesk → Veritabanları bölümünde ilgili veritabanına bağlı kullanıcıyı ve onun şifresini girin.</div><form method="post"><div class="grid"><label>MySQL Sunucu<input name="db_host" value="<?=ih($_POST['db_host']??'localhost')?>" required></label><label>Port<input name="db_port" value="<?=ih($_POST['db_port']??'3306')?>" required></label><label>Veritabanı Adı<input name="db_name" value="<?=ih($_POST['db_name']??'')?>" required></label><label>Veritabanı Kullanıcısı<input name="db_user" value="<?=ih($_POST['db_user']??'')?>" required></label><label class="full">Veritabanı Şifresi<input type="password" name="db_pass"></label><label class="full">Site Adresi<input name="site_url" value="<?=ih($_POST['site_url']??'https://iksiryayincilik.com/topluca')?>" required></label></div><div class="danger"><label><input style="width:auto;display:inline-block;margin-right:8px" type="checkbox" name="fresh" value="1"> Mevcut TOPLUCA tablolarını silip sıfırdan kur</label><p class="muted">Yalnızca TOPLUCA deneme veritabanında kullanın. Var olan sipariş, üye, ürün ve yönetim kayıtları silinir.</p><label>Onay<input name="confirm" placeholder="Sıfırlama seçiliyse: TOPLUCA SIFIRLA"></label></div><button>TOPLUCA V5.1'İ KUR</button></form><?php endif;?></div></div></body></html>